/**
 * @file commissioning_state.h
 * @brief Device commissioning state machine (ESP-IDF Native)
 * @generated by embedOS Code Generator
 *
 * Commissioning Flow Options:
 * - FULL: Uninitialized -> AP Mode -> Connecting -> Functional
 * - HARDCODED_WIFI: Uninitialized -> Connecting -> Functional (no AP mode)
 * - ALWAYS_AP: Always starts in AP mode for reconfiguration
 * - DIRECT: No commissioning, direct to functional (for development)
 */

#ifndef COMMISSIONING_STATE_H
#define COMMISSIONING_STATE_H

#include <stdint.h>

/**
 * Commissioning flow type for this device
 */
enum CommissioningFlow {
    FLOW_FULL = 0,           // Full AP provisioning flow
    FLOW_HARDCODED_WIFI = 1, // WiFi credentials in firmware
    FLOW_ALWAYS_AP = 2,      // Always start in AP for reconfiguration
    FLOW_DIRECT = 3          // Skip commissioning (development)
};

/**
 * Device commissioning states
 * States are dynamically enabled based on the selected flow
 */
enum CommissioningState {
    CS_UNINITIALIZED = 0,
    CS_AP_MODE_PROVISIONING = 1,
    CS_CONNECTING_TO_WIFI = 2,
    CS_WIFI_CONNECTED = 3,
    CS_FUNCTIONAL = 10,
    CS_ERROR = 99,
    CS_MAX_STATES
};

/**
 * Get readable name for a state
 */
static inline const char* getStateNameInternal(CommissioningState state) {
    switch (state) {
        case CS_UNINITIALIZED: return "Uninitialized";
        case CS_AP_MODE_PROVISIONING: return "AP Provisioning";
        case CS_CONNECTING_TO_WIFI: return "Connecting WiFi";
        case CS_WIFI_CONNECTED: return "WiFi Connected";
        case CS_FUNCTIONAL: return "Functional";
        case CS_ERROR: return "Error";
        default: return "Unknown";
    }
}

static inline const char *getStateName(CommissioningState state) {
    return getStateNameInternal(state);
}

/**
 * Current commissioning flow configuration
 */
#define COMMISSIONING_FLOW FULL

#endif // COMMISSIONING_STATE_H